package com.gathin.tvhome;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;
final class AmbientSlideshow{
 static JSONObject state(Context c)throws JSONException{SharedPreferences p=c.getSharedPreferences("background",0);return new JSONObject().put("enabled",p.getBoolean("slides_enabled",false)).put("seconds",p.getInt("slides_seconds",8)).put("ids",new JSONArray(p.getString("slides","[]")));}
 static List<File> files(Context c){List<File> result=new ArrayList<>();try{JSONObject s=state(c);if(!s.getBoolean("enabled"))return result;JSONArray ids=s.getJSONArray("ids");for(int i=0;i<ids.length();i++){File f=BackgroundStore.byId(c,ids.getString(i));if(f!=null&&BackgroundStore.kind(f).equals("image"))result.add(f);}}catch(Exception ignored){}return result;}
 static void save(Context c,JSONObject b)throws Exception{JSONArray ids=b.getJSONArray("ids"),clean=new JSONArray();int seconds=b.getInt("seconds");if(seconds<3||seconds>3600||ids.length()>30)throw new IllegalArgumentException("轮播间隔为3～3600秒，最多30张图");Set<String> seen=new HashSet<>();for(int i=0;i<ids.length();i++){String id=ids.getString(i);File f=BackgroundStore.byId(c,id);if(f==null||!BackgroundStore.kind(f).equals("image"))throw new IllegalArgumentException("轮播只能选择背景库中的图片");if(seen.add(id))clean.put(id);}if(b.getBoolean("enabled")&&clean.length()==0)throw new IllegalArgumentException("请先加入至少一张图片");c.getSharedPreferences("background",0).edit().putString("slides",clean.toString()).putInt("slides_seconds",seconds).putBoolean("slides_enabled",b.getBoolean("enabled")).putLong("revision",System.currentTimeMillis()).commit();}
}
